#!/usr/bin/env node
// gen-portal-setups.mjs — data/portal-setups.json (tools/particle-fx/
// portal_setups.py, from client_portal.dat) → scene3d/vfx/portal_setups.js,
// the runtime table the portal set piece (vfx/fx_showcase.js) keys on.
//
//   node scripts/gen-portal-setups.mjs            # write the module
//   node scripts/gen-portal-setups.mjs --check    # exit 1 if it is stale

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const APP = join(HERE, "..");
const SRC = join(APP, "data", "portal-setups.json");
const OUT = join(APP, "scene3d", "vfx", "portal_setups.js");
const KINDS = ["disc", "pillar", "dead", "dark"];

export function buildModule(doc) {
  const rows = [];
  for (const [hex, s] of Object.entries(doc.setups || {})) {
    const id = parseInt(hex, 16) >>> 0;
    if (!KINDS.includes(s.kind)) throw new Error(`${hex}: unknown kind ${s.kind}`);
    const c = s.centre.map((v) => +(+v).toFixed(4));
    const col = s.color.map((v) => +(+v).toFixed(4));
    const swirl = s.swirl ? `0x${(parseInt(s.swirl, 16) >>> 0).toString(16).toUpperCase().padStart(8, "0")}` : "0";
    rows.push(
      `  [0x${id.toString(16).toUpperCase().padStart(8, "0")}, Object.freeze({ kind: "${s.kind}", quadPart: ${s.quadPart | 0}, ` +
        `centre: Object.freeze([${c.join(", ")}]), radius: ${+(+s.radius).toFixed(4)}, ` +
        `color: Object.freeze([${col.join(", ")}]), swirl: ${swirl} })],`
    );
  }
  return [
    "// GENERATED by scripts/gen-portal-setups.mjs from data/portal-setups.json",
    "// (tools/particle-fx/portal_setups.py, client_portal.dat) — do not edit.",
    "// Every Setup built on the portal quad 0x0100168B whose default script spawns",
    "// something: kind (disc / pillar / dead / dark), the quad's part index, the",
    "// set piece's centre (Setup-local AC metres), disc radius, colour (max channel",
    "// 1) and main swirl emitter. See vfx/fx_showcase.js.",
    "",
    `export const PORTAL_QUAD_GFX = ${doc.portalQuad || "0x0100168B"};`,
    "export const PORTAL_SETUPS = new Map([",
    ...rows,
    "]);",
    "",
  ].join("\n");
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  const doc = JSON.parse(readFileSync(SRC, "utf8"));
  const text = buildModule(doc);
  if (process.argv.includes("--check")) {
    const cur = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
    if (cur !== text) {
      console.error(`${OUT} is stale — run node scripts/gen-portal-setups.mjs`);
      process.exit(1);
    }
    console.log("portal_setups.js up to date");
  } else {
    writeFileSync(OUT, text);
    console.log(`wrote ${OUT} (${Object.keys(doc.setups || {}).length} portal setups)`);
  }
}
